//! A real open shell must not prevent a disjoint solid from publishing recess evidence.
//! These original analytic STEP controls are generated by make_unowned_recess_fixtures.py.

use super::common;
use quiddity::correspondence;
use quiddity::evidence_view;
use quiddity::features::evidence::EvidenceStatus;
use quiddity::features::section_recess_family::build_section_recess_document;
use quiddity::recognition;

#[test]
fn unowned_recess_projection_errors_are_partial_not_silent_success() {
    let part =
        quiddity::read_step_file(&common::fixtures().join("unowned_recess_solid.step.gz")).unwrap();
    quiddity::features::take_inventory(&part, |ctx, mut inventory| {
        let levels = inventory.physical.step_levels.clone();
        assert!(!levels.is_empty());
        // Fault an otherwise body-owned candidate's publication contract. This returns
        // Err from SectionRecessEvidence::new; it does not panic or fail discovery.
        let walls = inventory.physical.defining["prismatic_pockets"][0].clone();
        inventory.constituent.get_mut("prismatic_pockets").unwrap()[0]
            .retain(|face| !walls.contains(face));
        let found = quiddity::features::recognise_in(ctx, inventory.clone());
        let evidence = evidence_view::project_inventory(ctx, inventory).unwrap();
        for failures in [&found.failures, &evidence.result.failures] {
            let failure = failures
                .iter()
                .find(|f| f.family == "section_recesses")
                .unwrap();
            assert_eq!(failure.stage, "section_recess_projection");
            assert_eq!(
                failure.message.as_deref(),
                Some("defining faces must be constituent faces")
            );
            assert!(failure.blocked_by.is_empty());
        }
        assert_eq!(found.step_levels, levels);
        assert_eq!(evidence.result.step_levels, levels);
        assert!(evidence.features.iter().any(|f| f.family == "step_levels"));
        assert!(evidence.section_recesses.section_recesses.is_empty());
    })
    .unwrap();
}

#[test]
fn rust_snapshot_unowned_recesses() {
    let runs: Vec<_> = ["solid", "shell", "mixed"]
        .into_iter()
        .map(|name| {
            let part = quiddity::read_step_file(
                &common::fixtures().join(format!("unowned_recess_{name}.step.gz")),
            )
            .unwrap();
            let recognition = recognition::document(
                &correspondence::caller_space_recognise(&part),
                part.faces.len(),
            );
            let evidence = evidence_view::document(&part, false).unwrap();
            serde_json::json!({"name": name, "recognition": recognition, "evidence": evidence})
        })
        .collect();
    common::snapshot::check(
        &common::fixtures(),
        "unowned_recesses",
        &serde_json::json!(runs),
    );
}

#[test]
fn unowned_recess_controls_keep_independent_evidence_and_source_identity() {
    for (name, solids, free_faces) in [("solid", 1, 0), ("shell", 0, 4), ("mixed", 1, 4)] {
        let part = quiddity::read_step_file(
            &common::fixtures().join(format!("unowned_recess_{name}.step.gz")),
        )
        .unwrap();
        assert_eq!(part.solids.len(), solids, "{name}");
        let unowned: Vec<_> = part
            .faces
            .iter()
            .enumerate()
            .filter_map(|(i, f)| f.solid.is_none().then_some(i))
            .collect();
        assert_eq!(unowned.len(), free_faces, "{name}");
        let rec = correspondence::caller_space_recognise(&part);
        let doc = recognition::document(&rec, part.faces.len());
        let evidence =
            evidence_view::document(&part, false).expect("local refusal, not whole-run error");
        assert!(doc.failures.is_empty(), "{name}: {:?}", doc.failures);
        assert!(
            evidence.failures.is_empty(),
            "{name}: {:?}",
            evidence.failures
        );
        assert_eq!(doc.complete, None);
        assert_eq!(evidence.complete, None);
        let refusals: Vec<_> = doc
            .records
            .iter()
            .filter(|r| r.family == "section_recess_source_refusals")
            .collect();
        assert_eq!(refusals.len(), usize::from(free_faces != 0), "{name}");
        for refusal in refusals {
            assert!(refusal.is_refusal());
            assert_eq!(refusal.evidence_status, EvidenceStatus::Unproved);
            assert_eq!(refusal.faces, unowned);
            assert_eq!(refusal.parameters["reason"], "missing_common_valid_solid");
            assert!(!refusal.parameters.contains_key("body"));
            let proof = evidence
                .features
                .iter()
                .find(|r| r.family == refusal.family)
                .unwrap();
            assert_eq!(proof.defining_faces, refusal.faces);
            assert_eq!(proof.constituent_faces, refusal.faces);
            assert_eq!(
                proof.record,
                serde_json::to_value(&refusal.parameters).unwrap()
            );
        }
        let recesses: Vec<_> = doc
            .records
            .iter()
            .filter(|r| r.family == "section_recesses" && !r.is_refusal())
            .collect();
        assert_eq!(recesses.len(), solids, "{name}");
        for recess in recesses {
            assert_eq!(recess.evidence_status, EvidenceStatus::Verified);
            assert!(recess.faces.iter().all(|&f| part.faces[f].solid.is_some()));
            let proof = evidence
                .features
                .iter()
                .find(|r| r.family == recess.family && r.defining_faces == recess.faces)
                .unwrap();
            assert_eq!(proof.record["geometry"], recess.parameters["geometry"]);
        }
        for (i, source) in evidence.face_sources.iter().enumerate() {
            let source = source.as_ref().expect("STEP face source retained");
            let original = part.face_source(i).unwrap();
            assert_eq!(
                (source.entity, source.instance),
                (original.entity, original.instance)
            );
        }
        if name == "shell" {
            let raw = doc
                .records
                .iter()
                .find(|r| r.family == "prismatic_pockets")
                .unwrap();
            assert_eq!(raw.evidence_status, EvidenceStatus::Unproved);
            assert_eq!(raw.parameters["depth"], 4.0);
            assert_eq!(raw.parameters["sides"], 3);
            // Current main also attaches the analytically proved flat floor. Its
            // face claim still does not upgrade the shell's material proof.
            assert_eq!(raw.faces, unowned);
        }
        let section = build_section_recess_document(&part).unwrap();
        assert_eq!(section.occurrences().len(), solids);
        assert_eq!(
            section.source_refusals().len(),
            usize::from(free_faces != 0)
        );
    }
}
